    uint8_t version;
    bool parity;
};

static tap parse(const data_chunk&amp; control) NOEXCEPT
{
    BC_ASSERT(!control.empty());

    const auto byte = control.front();
    return
    {
        bit_and(byte, tapscript_mask),
        to_bool(bit_and(byte, bit_not(tapscript_mask)))
    };
}

